 91	pub enum SymbolTableEntry {
 92	    Variable(TypeKind, Value),
 93	    Constant(TypeKind, i32),
 94	}
 95	
 96	impl std::fmt::Debug for SymbolTableEntry {
 97	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
 98	        match self {
 99	            SymbolTableEntry::Variable(tk, v) => write!(f, "Variable({}): {:?}", tk, v),
100	            SymbolTableEntry::Constant(tk, v) => write!(f, "Constant({}): {:?}", tk, v),
101	        }
102	    }
103	}
104	
105	pub enum IRBuildResult {
106	    OK,
107	    EARLYSTOPPING,
108	}
109	
110	pub trait IRBuildable {
111	    fn build(
112	        &self,
113	        program: &mut Program,
114	        my_ir_generator_info: &mut MyIRGeneratorInfo,
115	    ) -> Result<IRBuildResult, String>;
116	}
117	
118	impl IRBuildable for CompUnit {
119	    fn build(
120	        &self,
121	        program: &mut Program,
122	        my_ir_generator_info: &mut MyIRGeneratorInfo,
123	    ) -> Result<IRBuildResult, String> {
124	        todo!()
125	    }
126	}
127	
128	impl IRBuildable for Unit {
129	    fn build(
130	        &self,
131	        program: &mut Program,
132	        my_ir_generator_info: &mut MyIRGeneratorInfo,
133	    ) -> Result<IRBuildResult, String> {
134	        match self {
135	            Unit::Decl(d) => d.build(program, my_ir_generator_info),
136	            Unit::FuncDef(f) => f.build(program, my_ir_generator_info),
137	        }
138	    }
139	}
140	
141	fn get_valuedata(
142	    value: Value,
143	    program: &mut Program,
144	    my_ir_generator_info: &mut MyIRGeneratorInfo,
145	) -> ValueData {
146	    if value.is_global() {
147	        program.borrow_value(value).clone()
148	    } else {
149	        program
150	            .func(my_ir_generator_info.curr_func.unwrap())
151	            .dfg()
152	            .value(value)
153	            .clone()
154	    }
155	}
156	
157	/// Helper function to build a new value.
158	fn create_new_local_value<'a>(
159	    program: &'a mut Program,
160	    my_ir_generator_info: &'a mut MyIRGeneratorInfo,
161	) -> koopa::ir::builder::LocalBuilder<'a> {
162	    program
163	        .func_mut(
164	            my_ir_generator_info
165	                .curr_func
166	                .expect("You should use create_new_global_value when curr_func is None! "),
167	        )
168	        .dfg_mut()
169	        .new_value()
170	}
171	
172	/// Helper function to build a new basic block.
173	fn create_new_block<'a>(
174	    program: &'a mut Program,
175	    my_ir_generator_info: &'a mut MyIRGeneratorInfo,
176	    name: &str,
177	) -> BasicBlock {
178	    let block = program
179	        .func_mut(my_ir_generator_info.curr_func.unwrap())
180	        .dfg_mut()
181	        .new_bb()
182	        .basic_block(Some(format!("%bb{}_{}", my_ir_generator_info.bb_cnt, name)));
183	    my_ir_generator_info.bb_cnt += 1;
184	    block
185	}
186	
187	/// Helper function to insert instructions into the current function's data flow graph.
188	fn insert_local_instructions<T>(
189	    program: &mut Program,
190	    my_ir_generator_info: &mut MyIRGeneratorInfo,
191	    instructions: T,
192	) where
193	    T: IntoIterator<Item = Value>,
194	{
195	    program
196	        .func_mut(my_ir_generator_info.curr_func.unwrap())
197	        .layout_mut()
198	        .bb_mut(my_ir_generator_info.curr_block.unwrap())
199	        .insts_mut()
200	        .extend(instructions);
201	}
202	
203	/// Helper function to insert basic blocks into the current function's data flow graph.
204	fn insert_basic_blocks<T>(
205	    program: &mut Program,
206	    my_ir_generator_info: &mut MyIRGeneratorInfo,
207	    basic_blocks: T,
208	) where
209	    T: IntoIterator<Item = BasicBlock>,
210	{
211	    program
212	        .func_mut(my_ir_generator_info.curr_func.unwrap())
213	        .layout_mut()
214	        .bbs_mut()
215	        .extend(basic_blocks);
216	}
217	
218	fn build_shape(
219	    shape_exps: &Vec<Exp>,
220	    program: &mut Program,
221	    my_ir_generator_info: &mut MyIRGeneratorInfo,
222	) -> Result<Vec<usize>, String> {
223	    let mut result = vec![];
224	    for exp in shape_exps {
225	        match exp.build(program, my_ir_generator_info)? {
226	            IRExpBuildResult::Const(int) => result.push(int as usize),
227	            IRExpBuildResult::Value(_) => {
228	                return Err(format!("The shape of array must be constant! "))
229	            }
230	        }
231	    }
232	    Ok(result.clone())
233	}
234	
235	fn get_array_type(btype: &BType, shape: &[usize]) -> TypeKind {
236	    if shape.is_empty() {
237	        return btype.content.clone();
238	    }
239	    let inner_typekind = get_array_type(btype, &shape[1..]);
240	    TypeKind::Array(Type::get(inner_typekind), shape[0])
241	}
