    58	            register_used_time: [0; 32],
    59	            local_value_location: HashMap::new(),
    60	        }
    61	    }
    62	
    63	    fn __update_user(&mut self, reg: usize, user: Value) {
    64	        self.curr_time += 1;
    65	        self.register_user[reg] = Some(user);
    66	        self.register_used_time[reg] = self.curr_time;
    67	    }
    68	    fn __free_user(&mut self, reg: usize) {
    69	        self.register_user[reg] = None;
    70	        self.register_used_time[reg] = 0;
    71	    }
    72	
    73	    fn __is_value_in_register(&self, value: Value) -> Option<usize> {
    74	        for i in 0..REGISTER_NAMES.len() {
    75	            match self.register_user[i] {
    76	                Some(v) => {
    77	                    if v == value {
    78	                        return Some(i);
    79	                    }
    80	                }
    81	                None => {}
    82	            }
    83	        }
    84	        None
    85	    }
